import csv
import json


def answer() -> int:
    qualifying_children = {("Liwia", "Maligłówka")}
    total = 0

    with open("/app/dataset/people_accounts.csv", newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            if (row["first_name"], row["last_name"]) in qualifying_children:
                total += int(row["account_balance"])

    return total


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as f:
        json.dump(answer(), f, default=list)
